{
  "name": "快速XAFS扫描控制组件",
  "name_en": "Quick XAFS Scan Controller",
  "manufacturer": "",
  "description": "用于配置和执行快速X射线吸收精细结构扫描的非实体软件组件。它负责连接扫描相关控制点、生成基于能量与停留时间的运动轨迹、启动扫描采集、将聚集数据换算为能量信息，并在扫描结束后整理与保存数据。",
  "description_en": "A non-physical software component for configuring and executing quick X-ray absorption fine structure scans. It connects scan-related control points, generates motion trajectories from energy and dwell settings, starts scan acquisition, converts gathered data into energy-related results, and performs post-scan data handling and saving.",
  "actions": [
    {
      "action_name": "auto-connect_qxafs",
      "description": "连接并初始化QXAFS扫描所需的控制点和相关配置。",
      "description_en": "Connect and initialize the control points and related configuration required for a QXAFS scan."
    },
    {
      "action_name": "auto-finish_qscan",
      "description": "完成QXAFS扫描的收尾与结束处理。",
      "description_en": "Finalize and complete the end-of-scan handling for a QXAFS scan."
    },
    {
      "action_name": "auto-gathering2energy",
      "description": "读取聚集数据文本，并换算得到能量与高度结果。",
      "description_en": "Read gathered data text and convert it into energy and height results."
    },
    {
      "action_name": "auto-make_trajectory",
      "description": "根据目标能量点和停留时间生成QXAFS扫描运动轨迹。",
      "description_en": "Generate the QXAFS scan motion trajectory from target energy points and dwell times."
    },
    {
      "action_name": "auto-post_scan",
      "description": "执行扫描结束后的数据整理、计时显示或保存等后处理步骤。",
      "description_en": "Perform post-scan processing such as data organization, timing display, or saving."
    },
    {
      "action_name": "auto-run",
      "description": "运行一次完整的QXAFS扫描流程，包括准备、采集、读取和整理数据。",
      "description_en": "Run a complete QXAFS scan workflow, including preparation, acquisition, data reading, and data organization."
    },
    {
      "action_name": "auto-set_energy_pv",
      "description": "设置用于能量控制的过程变量。",
      "description_en": "Set the process variable used for energy control."
    },
    {
      "action_name": "auto-add_region",
      "description": "添加一个扫描区域定义。",
      "description_en": "Add a scan region definition."
    }
  ],
  "tag_hints": [
    "QXAFS",
    "XAFS scan control",
    "EPICS PV",
    "trajectory generation",
    "synchrotron beamline",
    "data acquisition orchestration",
    "Newport XPS"
  ]
}

